<?php require __DIR__.'/includes/functions.php'; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$msg=trim($_POST['message']??''); if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&$msg){$pdo->prepare('CREATE TABLE IF NOT EXISTS contact_messages(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150),email VARCHAR(200),message TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP)')->execute();$pdo->prepare('INSERT INTO contact_messages(name,email,message) VALUES(?,?,?)')->execute([$name,$email,$msg]);} } header('Location: index.php?sent=1#contact');
